return {
  [ [[v5748eaic9t4f]] ] = { t = [[音爆强袭者的怪异之音]], q = [[音爆强袭者的怪异之音能力让人一头雾水。它能对同一个目标生效多次吗？裁定它需要掷30次骰吗？]], a = [=[将怪异之音的文字改为如下：“6级时，吟游诗人可以开始一场表演（始终为标准动作），说出至多每4个吟游诗人等级1个、饱含音波能量的字。每个字以远程[[接触攻击]]造成4d6点音波伤害，射程30尺。吟游诗人将自己的[[魅力]]调整值加到怪异之音的伤害掷骰上。击中同一目标的多个字合并为一次强力攻击，能量抗力和伤害掷骰加值只计算一次。吟游诗人可以让所有字指向同一目标或不同目标，但所有字同时释放。每个字消耗1轮吟游表演。”这一修改将体现在今后的勘误中。]=], book = [[极限魔法]], date = [[2015/01/03]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fz#v5748eaic9t4f]], cat = [[FAQ]], ai = false, pages = { [[音爆强袭者]] } },
  [ [[v5748eaic9obe]] ] = { t = [[混源学者的两类攻击]], q = [[混源学者（第80页）能在同一轮里既用自己身体发动的攻击（如人造武器、徒手攻击或天生攻击），又用融合幻灵的攻击吗？]], a = [=[可以，但融合后角色的天生攻击仍受[[幻灵]]表格中对应等级的“攻击上限”一项限制。例如，1级混源学者每轮最多进行3次天生攻击，无论这些天生攻击来自幻灵、混源学者本人，还是两者的组合。

若混源学者想在同一轮既使用幻灵的天生攻击，又使用自己的人造武器或天生武器，幻灵就需要有足够的肢体来承担所有这些攻击。例如，融合了双臂二足型幻灵的侏儒混源学者有两条手臂可用于攻击；如果他想用幻灵的爪抓攻击，同时又要进行武器攻击（比如用匕首或木棍），就得给幻灵添上额外的臂进化来握持这些武器（视为召唤师自身肢体的延伸）——双臂幻灵不能在同一轮里既进行两次爪抓攻击，又进行匕首攻击或木棍攻击。

请记住，混源学者仍受同一轮中混用人造武器攻击和天生武器攻击的规则约束（天生武器始终视为次要武器，因此有-5攻击减值）。

还请记住，召唤师是把幻灵像一层包裹全身的生物“外装”一样穿在身上，幻灵的形态会限制召唤师能做的事。如果幻灵没有臂，召唤师就无法用自己的手臂操纵物体、进行攻击、施放需要姿势成分的法术，或做任何需要手臂的事——融合时，召唤师的肢体被困在无臂的幻灵外装之内，无法用来操纵物品。召唤师也无法把自己的身体部位伸出幻灵外装之外；他若想用手臂操纵物体，幻灵就得有臂（不过对简单的任务来说，触手就够了）。

（注：混源学者是悬浮不动地待在幻灵外装里、由其意念驱动幻灵的肢体，还是混源学者活动自己的手臂、幻灵外装的手臂跟着重复这些动作，抑或幻灵外装更贴身、包裹着血肉的肢体直接随混源学者自己的动作而动，这都属于风味和玩家喜好的问题。）

注：本条澄清了较早FAQ中的一处错误，当时把召唤师的武器攻击也计入了表格中的攻击次数。]=], book = [[极限魔法]], date = [[2011/01/08]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fz#v5748eaic9obe]], cat = [[FAQ]], ai = false, pages = { [[混源学者]] } },
  [ [[v5748eaic9obb]] ] = { t = [[混源学者与技能精通]], q = [[混源学者（第80页）能从技能精通进化中获益吗？尽管他的幻灵本身没有技能。属性强化进化用在心智属性上呢？]], a = [=[如果混源学者的幻灵拥有[[幻灵/技能精通|技能精通]]进化，混源学者获得该技能的加值。

如果混源学者把[[幻灵/属性强化|属性强化]]进化用在幻灵的心智属性上，对混源学者没有任何效果，因为他使用的是自己的心智属性值。]=], book = [[极限魔法]], date = [[2011/01/08]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fz#v5748eaic9obb]], cat = [[FAQ]], ai = false, pages = { [[混源学者]] } },
  [ [[v5748eaic9obd]] ] = { t = [[混源学者对自身施法]], q = [[混源学者（第80页）能对自己施放不影响异界生物的法术吗？尽管他被视为自己原本的生物类别或异界生物，“取其较糟者”？]], a = [=[可以。因为一般幻灵的法术共享能力写明“即使这些法术通常不影响幻灵的生物类型（异界生物），召唤师也可以对幻灵施放”，而混源学者变体并未改变这一点。

