如果该生物豁免成功，则它改为因悲伤而僵住1轮，期间无法采取任何行动，且AC受到-2减值，之后法术结束。]], book = [[极限魔法]], date = [[2011/01/07]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fz#v5748eaic9o7h]], cat = [[FAQ]], ai = false, pages = { [[深沉忏悔]] } },
  [ [[v5748eaic9o7r]] ] = { t = [[通灵法术的前置条件]], q = [[通灵法术（第157页）的前置条件是什么？表格与专长条目（第147页）不一致。]], a = [[第157页的文字是正确的。

